WITH exploded AS (SELECT base.id, base.created_at, line.product_id, line.qty, line.price, line.promo FROM carts base LATERAL VIEW EXPLODE(base.items) x AS line) SELECT created_at, product_id, qty, promo, CASE WHEN promo RLIKE '^(SPRING10|WELCOME5)$' THEN 'OTHER_ZONE' WHEN promo RLIKE '^(VIP|BUNDLE)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS promo_zone FROM exploded ORDER BY qty DESC NULLS FIRST
